// OFL-licensed Google Fonts bundled as data URLs so text works offline.
const FONTNAMES=["Poppins", "Inter", "Oswald", "Bebas Neue", "Anton", "Playfair Display", "Merriweather", "Lobster", "Pacifico", "Caveat", "Space Mono"];
const FONTDATA={
'Poppins':'data:font/woff2;base64,',
'Inter':'data:font/woff2;base64,',
'Oswald':'data:font/woff2;base64,',
'Bebas Neue':'data:font/woff2;base64,',
'Anton':'data:font/woff2;base64,',
'Playfair Display':'data:font/woff2;base64,',
'Merriweather':'data:font/woff2;base64,',
'Lobster':'data:font/woff2;base64,',
'Pacifico':'data:font/woff2;base64,',
'Caveat':'data:font/woff2;base64,',
'Space Mono':'data:font/woff2;base64,',
};
let _fontsReady=null;
function ensureFonts(){
  if(_fontsReady)return _fontsReady;
  _fontsReady=Promise.all(FONTNAMES.map(async n=>{try{const f=new FontFace(n,`url(${FONTDATA[n]})`);await f.load();document.fonts.add(f)}catch(e){}}));
  return _fontsReady;
}
